package com.example.signlanguagetranslatorapp

import org.junit.Assert.assertEquals
import org.junit.Assert.assertTrue
import org.junit.Test
import java.io.File

/**
 * golden.csv = feature vectors + the prediction scikit-learn made for them
 * (generated by tools/export_rf_model.py). The Kotlin forest must agree on every row.
 */
class RandomForestModelTest {

    private fun loadModel() =
        File("src/main/assets/rf_model.bin").inputStream().use { RandomForestModel.load(it) }

    @Test
    fun modelHasExpectedShape() {
        val model = loadModel()
        assertEquals(42, model.nFeatures)
        assertEquals(100, model.treeCount)
    }

    @Test
    fun matchesScikitLearnOnGoldenVectors() {
        val model = loadModel()
        val lines = javaClass.getResourceAsStream("/golden.csv")!!.bufferedReader().readLines().filter { it.isNotBlank() }
        assertTrue(lines.size >= 100)
        for ((i, line) in lines.withIndex()) {
            val parts = line.split(",")
            val features = FloatArray(42) { parts[it].toFloat() }
            val expected = parts[42].toInt()
            assertEquals("row $i", expected, model.predict(features).label)
        }
    }

    @Test(expected = IllegalArgumentException::class)
    fun rejectsWrongFeatureCount() {
        loadModel().predict(FloatArray(84))
    }
}
